vec2 rot2D(vec2 v, int nb)
{
    mat2 m = mat2(0.80,  0.60,
                  -0.60,  0.80);
    for (int i = 0; i < nb; i += 1)
        v *= m;
    return v;
}

float st(float x) {
   // to avoid every computations possible, let's assume we only use this func when already clamped
   return x * x * (3.0f - 2.0f * x);
}

float a_corner(float i, float j) {
    vec2 f = 50. * vec2(fract(i / 3.1415), fract(j / 3.1415));
    return fract((f.x + 2.0) * (f.y + 1.4) * (f.x + f.y)) * 2.;
}

float polynomial(float x, float z)
{
    float i = floor(x);
    float j = floor(z);

    float a = a_corner(i, j); 
    float b = a_corner(i + 1., j);
    float c = a_corner(i, j + 1.);
    float d = a_corner(i + 1., j + 1.);

    return a+(b - a)*st(x - i)+(c - a)*st(z - j)+(a-b-c+d)*st(x-i)*st(z-j);
}

float tH(vec3 pos)
{
    float d = polynomial(pos.x, pos.z) * 0.5;
    if (d < 0.0)
        d *= 0.5;
    float p = 4.;
    vec3 tpos = pos;
    for (int i = 0; i < 8; i += 1) {
        tpos *= 2.;
        tpos.xz = rot2D(tpos.xz, 1);
        d += (polynomial(tpos.x, tpos.z) / p);
        p *= 2.;
    }

    if (d < 0.7)
        d += (0.7 - d)/1.8;

    return d;
}

float stH(vec3 pos)
{
    float d = polynomial(pos.x, pos.z) * 0.5;
    if (d < 0.0)
        d *= 0.5;
    float p = 4.;
    vec3 tpos = pos;
    for (int i = 0; i < 4; i += 1) {
        tpos *= 2.;
        tpos.xz = rot2D(tpos.xz, 1);
        d += (polynomial(tpos.x, tpos.z) / p);
        p *= 2.;
        if (i == 4)
            i = 10;
    }

    if (d < 0.7)
        d += (0.7 - d)/1.8;

    return d;
}

float map(in vec3 pos)
{
    float d = tH(pos);

    return pos.y - d;
}

vec3 calcNormal(in vec3 p)
{
    vec3 normal = vec3(tH(vec3(p.x - 0.001, p.y, p.z)) - tH(vec3(p.x + 0.001, p.y, p.z)),
                        0.001,
                        tH(vec3(p.x, p.y, p.z - 0.001)) - tH(vec3(p.x, p.y, p.z + 0.001)));
    return normalize(normal);
}

vec3 calcNormalTree(in vec3 pos)
{

    float s = 120.;
    vec2 fp = vec2(floor(pos.x*s)/s + 0.5/s, floor(pos.z*s)/s + 0.5/s);
    vec3 tp = vec3(fp.x, stH(vec3(fp.x, 0., fp.y)) + 0.01, fp.y);

    return normalize(pos - tp);
}

float getSDFSphere(vec3 pos)
{
    float s = 120.;
    vec2 fp = vec2(floor(pos.x*s)/s + 0.5/s, floor(pos.z*s)/s + 0.5/s);
    float h = stH(vec3(fp.x, 0., fp.y));
    vec3 tp = vec3(fp.x + fract(h*fp.y*3.14)*0.02 - 0.01, h + 0.01, fp.y + fract(h*fp.x*3.14)*0.02 - 0.01);
    float d = length(pos - tp) - 0.01;

    for (int i = 0; i < 2; i += 1) {
        for (int j = 0; j < 2; j += 1) {
            vec2 Nfp = vec2(fp.x + float(i)*1./s - 1./s, fp.y + float(j)*1./s - 1./s);
            float h = stH(vec3(Nfp.x, 0., Nfp.y));
            tp = vec3(Nfp.x + fract(h*Nfp.y*3.14)*0.02 - 0.01, h + 0.01, Nfp.y + fract(h*Nfp.x*3.14)*0.02 - 0.01);
            float dd = length(pos - tp) - 0.01;
            d = min(dd, d);
        }
    }
    return d;
}

vec3 castRay(vec3 ro, vec3 rd)
{
    float t = 0.0;
    int i = 0;
    float h = 0.;
    float v = 0.;
    for (; i < 1000; i++)
    {
        vec3 pos = ro + rd*t;

        v = map(pos);
        if (v < 0.) {
            while (h > 0.0001) {
                h /= 2.;
                if (v < 0.) {
                    t -= h;
                    pos = ro + rd*t;
                    v = map(pos);
                } else {
                    t += h;
                    pos = ro + rd*t;
                    v = map(pos);
                }
            }
            break;
        }
        float tree = getSDFSphere(pos);

        if (tree < 0.001)
            return vec3(t, float(i), 1.);

        h = min(0.1 * clamp(t, 1., 100.0), tree); //step skip spheres

        t += h;
        if (t >= 200.) break;
    }
    if (v > 0.01)
        t = -1.;
    if (t > 200.)
        t = -1.;
    return vec3(t, float(i), 0.);
}

float sh(vec3 ro, vec3 sun_dir)
{
    float t = 0.1;
    int i = 0;
    float h = 0.;
    float v = 100.;
    for (; i < 100; i++)
    {
        vec3 pos = ro + sun_dir*t;

        float nv = map(pos) * 0.1;
        nv = 32. * (nv)/t;

        v = min(nv, v);

        h = 0.05 * clamp(t, 1., 200.0);

        t += h;
        if (t >= 10.) break;
    }
    return smoothstep(0., 1., v);
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = (2.0*fragCoord-iResolution.xy)/iResolution.y;

    //raymarching
    vec3 ro = vec3(0.72, 0.75, -0.09);
    vec3 ta = ro + vec3(sin(-0.6) * 5., 0., cos(-0.6) * 5.); //target point

    vec3 ww = normalize(ta - ro);
    vec3 uu = normalize(cross(ww, vec3(0., 1., 0.))); // find side
    vec3 vv = normalize(cross(uu, ww)); //find up

    vec3 rd = normalize(vec3(uv.x*uu + uv.y*vv + 1.8*ww)); // -1.5 is the near plane position


    vec3 skyCol = vec3(.4, .75, 1.) - .7*rd.y;
    skyCol = mix(skyCol, vec3(.7, .75, .8), exp(-10. * rd.y));
    vec3 col = skyCol;

    vec3 t = castRay(ro, rd);

    if (t.x > 0.) {
        vec3 pos = ro + rd*t.x;
        vec3 normal;
        if (t.z < 0.5)
            normal = calcNormal(pos);
        else
            normal = calcNormalTree(pos);

        vec3 sun_dir = normalize(vec3(1.3, 0.5, 0.44));
        float penumbra = 1.;
        penumbra = sh(pos, sun_dir);

        vec3 matGround = vec3(0.7, 0.4, 0.2);
        vec3 matGrass = vec3(0.35, 0.5, 0.05);
        vec3 mat = mix(matGround, matGrass, smoothstep(0.4, 0.7, normal.y));
        if (t.z > 0.5) {
            mat = vec3(0.25, 0.4, 0.02);
        }

        float d = max(0., dot(normal, sun_dir));
        d *= penumbra;

        float b = max(0., dot(normal, -sun_dir));
        vec3 bounceCol = mat / 20.;

        col = d * mat + ((1. + normal.y)/2.) * vec3(.7, .75, .8)/20. + b * bounceCol;
    }
    float athmos = exp(-0.08 * t.x);
    col = col * athmos + (1. - athmos) * vec3(0.9, 0.9, 0.9);

    col = smoothstep(0., 1., col);

    col = pow(col, vec3(0.4545));


    fragColor = vec4(col,1.0);
}
